def t(en_text, te_text):
    lang = st.session_state.get('app_language', 'English + తెలుగు')
    if lang == 'English':
        return en_text
    elif lang == 'తెలుగు':
        return te_text
    else:
        return f"{en_text} / {te_text}"

def t_block(en_text, te_text):
    lang = st.session_state.get('app_language', 'English + తెలుగు')
    if lang == 'English':
        return f"<div>{en_text}</div>"
    elif lang == 'తెలుగు':
        return f"<div>{te_text}</div>"
    else:
        return f"<div>{en_text}</div><div style='color:#0369A1; font-size:0.85em; margin-top:2px;'>{te_text}</div>"

